// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /chat/send').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Soru isteğini doğrular.
const b = $('POST /chat/send').first().json.body || {};
const user_id = $('Soru: oturum').first().json.user_id;
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
const message = s(b.message);
if (!message || message.length > 4000) {
  return [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message: 'Mesaj 1-4000 karakter arasında olmalıdır.' } } } }];
}
return [{
  json: {
    valid: true,
    user_id,
    message,
    conversation_id: s(b.conversation_id) || null,
    course_id: s(b.course_id) || null,
    model: s(b.model) || null,
  },
}];

// Sohbeti çözer (var olan / yeni), modele gidecek mesajları ve kaydedilecek belgeleri hazırlar.
const crypto = require('crypto');
const v = $('Soru: doğrula').first().json;
const conv = $('Soru: sohbet bul').first().json || {};
const course = $('Soru: ders bul').first().json || {};
const notes = $('Soru: notlar').all().map((i) => i.json).filter((d) => d && d.id);
const history = $('Soru: geçmiş').all().map((i) => i.json).filter((d) => d && d.id)
  .sort((a, b) => a.seq - b.seq);

const notFound = (message) => [{ json: { valid: false, response: { ok: false, error: { code: 'NOT_FOUND', message } } } }];
if (v.conversation_id && !conv.id) return notFound('Sohbet bulunamadı.');
if (!v.conversation_id && v.course_id && !course.id) return notFound('Ders bulunamadı.');

const isNew = !conv.id;
const courseId = isNew ? (course.id || null) : (conv.course_id || null);
const courseName = courseId && course.id === courseId ? course.name : null;

// Ders notları bağlamı: özet varsa özet, yoksa not metni; en fazla 6000 karakter
const noteText = (n) => (n.summary && n.summary.short)
  ? [n.summary.short, ...(n.summary.key_points || []).map((p) => '- ' + p)].join('\n')
  : n.content;
const notesContext = notes.map((n) => `### ${n.title}\n${noteText(n)}`).join('\n\n').slice(0, 6000);

let system = [
  'Sen üniversite öğrencilerine ders çalışmada yardım eden bir yapay zekâ asistanısın.',
  'KURALLAR:',
  '1. Yanıtını YALNIZCA Türkçe yaz. Çince, Japonca, Korece veya Kiril alfabesinden tek bir karakter bile kullanma.',
  '2. Açık, doğru ve öğretici ol; gerekiyorsa kısa bir örnek ver.',
  '3. Emin olmadığın bilgiyi uydurma; bilmiyorsan bunu açıkça söyle.',
  '4. Yanıtın en fazla 250 kelime olsun.',
].join('\n');
if (notesContext) {
  system += `\n\nAşağıda öğrencinin "${courseName}" dersine ait notları var. ` +
    'Soruyu öncelikle bu notlara dayanarak yanıtla. Notlarda olmayan bir bilgi verirsen bunun ' +
    `genel bilgi olduğunu belirt.\n\n<notlar>\n${notesContext}\n</notlar>`;
}

const now = Date.now();
const nowIso = new Date(now).toISOString();
const conversation = isNew
  ? { id: crypto.randomUUID(), user_id: v.user_id, course_id: courseId,
      title: v.message.replace(/\s+/g, ' ').slice(0, 60), created_at: nowIso, updated_at: nowIso }
  : { id: conv.id, updated_at: nowIso };

return [{
  json: {
    valid: true,
    is_new: isNew,
    conversation,
    user_message: { id: crypto.randomUUID(), conversation_id: conversation.id, user_id: v.user_id,
      role: 'user', content: v.message, model: null, seq: now, created_at: nowIso },
    model: v.model, // null ise HTTP düğümü .env içindeki LLM_MODEL'i kullanır
    messages: [
      { role: 'system', content: system },
      ...history.map((m) => ({ role: m.role, content: m.content })),
      { role: 'user', content: v.message },
    ],
  },
}];

// Ollama yanıtını doğrular. $runIndex: bu düğümün bu çalıştırmadaki kaçıncı turu (0'dan başlar).
const r = $input.first().json;
const content = (r.message && typeof r.message.content === 'string') ? r.message.content.trim() : '';
// Çince/Japonca/Korece ve Kiril karakterleri
const foreign = /[぀-ヿ㐀-䶿一-鿿豈-﫿가-힯Ѐ-ӿ]/;

let problem = null;
if (!content) problem = 'boş yanıt';
else if (foreign.test(content)) problem = 'Türkçe dışı karakter';

return [{
  json: { valid: problem === null, problem, attempt: $runIndex + 1, content, model: r.model || null },
}];

// Kaydedilecek sohbet belgesi + doğrulanmış model yanıtı (sonraki düğüm için)
const p = $('Soru: hazırla').first().json;
const r = $input.first().json; // "Yanıtı doğrula" çıktısı
return [{ json: { ...p.conversation, _reply: { content: r.content, model: r.model } } }];

// Kullanıcı ve asistan mesaj belgelerini (2 öğe) ve istemci yanıtını hazırlar.
const crypto = require('crypto');
const p = $('Soru: hazırla').first().json;
const reply = $('Soru: sohbet belgesi').first().json._reply;
const userMsg = p.user_message;
const now = Date.now();
const assistant = {
  id: crypto.randomUUID(), conversation_id: p.conversation.id, user_id: userMsg.user_id,
  role: 'assistant', content: reply.content, model: reply.model || null,
  seq: Math.max(now, userMsg.seq + 1), created_at: new Date(now).toISOString(),
};
const response = {
  ok: true,
  data: {
    conversation_id: p.conversation.id,
    reply: { id: assistant.id, role: 'assistant', content: assistant.content,
             model: assistant.model, created_at: assistant.created_at },
  },
};
return [{ json: { ...userMsg, response } }, { json: assistant }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /chat/conversations').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Sohbet listesi sorgusu (isteğe bağlı ders filtresi)
const b = $('POST /chat/conversations').first().json.body || {};
const user_id = $('Sohbetler: oturum').first().json.user_id;
const course_id = b.course_id ? String(b.course_id).trim() : '';
return [{ json: { user_id, query: course_id ? { user_id, course_id } : { user_id } } }];

// Sohbetleri ders adı, mesaj sayısı ve son mesajla birleştirir.
const iso = (v) => (v ? new Date(v).toISOString() : null);
const rows = (node) => $(node).all().map((i) => i.json).filter((d) => d && d.id);
const courses = Object.fromEntries(rows('Sohbetler: dersler').map((c) => [c.id, c.name]));
const msgs = rows('Sohbetler: mesajlar');

const conversations = rows('Sohbetler: sohbetler').map((c) => {
  const m = msgs.filter((x) => x.conversation_id === c.id).sort((a, b) => b.seq - a.seq);
  return {
    id: c.id,
    title: c.title,
    course_id: c.course_id ?? null,
    course_name: c.course_id ? (courses[c.course_id] ?? null) : null,
    message_count: m.length,
    last_message: m.length ? String(m[0].content).slice(0, 120) : null,
    updated_at: iso(c.updated_at),
  };
}).sort((a, b) => String(b.updated_at).localeCompare(String(a.updated_at)));

return [{ json: { response: { ok: true, data: { conversations } } } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /chat/history').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Bir sohbetin mesajlarını eskiden yeniye döndürür.
const iso = (v) => (v ? new Date(v).toISOString() : null);
const c = $('Geçmiş: sohbet').first().json;
const messages = $input.all().map((i) => i.json).filter((d) => d && d.id)
  .sort((a, b) => a.seq - b.seq)
  .map((m) => ({ id: m.id, role: m.role, content: m.content, model: m.model ?? null, created_at: iso(m.created_at) }));
return [{
  json: {
    response: {
      ok: true,
      data: { conversation: { id: c.id, title: c.title, course_id: c.course_id ?? null }, messages },
    },
  },
}];
